/**
 * Registration creates the user and their first workspace in one step — a
 * Taskflow account with no organization cannot do anything, so there is no
 * intermediate state where one exists without the other.
 */
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const email = input.email.toLowerCase();
  if (await userRepo.findUserByEmail(email)) throw new DuplicateEmailError();
  let user: User;
  try {
    user = await userRepo.insertUser({
      email,
      name: input.name,
      passwordHash: await hashPassword(input.password),
    });
  } catch (error) {
    if (await userRepo.findUserByEmail(email)) throw new DuplicateEmailError();
    throw error;
  }

  const workspaceSuffix = "'s workspace";
  const displayName = input.name.slice(0, 64 - workspaceSuffix.length);
  const nameSlug = slugify(input.name);
  const derivedSlug =
    nameSlug.length < SLUG_MIN_LENGTH
      ? "workspace"
      : isReservedSlug(nameSlug)
        ? uniqueSlug(nameSlug, [])
        : nameSlug;
  const org = await createOrganization(user.id, {
    name: `${displayName}${workspaceSuffix}`,
    slug: derivedSlug,
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

